   if(type===lua.LUA_TNIL)return {value:['nil']};
   if(type===lua.LUA_TBOOLEAN)return {value:['boolean',lua.lua_toboolean(L,index)]};
   if(type===lua.LUA_TNUMBER)return {value:['number',String(lua.lua_tonumber(L,index))]};
